class Solution {
public:
    int maximumProfit(vector<int>& present, vector<int>& future, int budget) {
        vector<int> dp(budget + 1);
        for (int i = 0; i < (int)present.size(); ++i)
            for (int money = budget; money >= present[i]; --money)
                dp[money] = max(dp[money], dp[money - present[i]] + future[i] - present[i]);
        return dp[budget];
    }
};
